    buy_book = []  # min-heap by price (ascending), then by arrival time
    sell_book = []  # max-heap by price (descending), then by arrival time
    resting = {}  # id -> (side, price, qty, arrival_index)
    next_arrival = [0]  # use list to allow mutation in nested function

    import heapq

    def add_limit_order(order_id, side, price, qty, arrival_index):
        resting[order_id] = (side, price, qty, arrival_index)
        if side == 'buy':
            heapq.heappush(buy_book, (-price, arrival_index, order_id))
        else:
            heapq.heappush(sell_book, (price, arrival_index, order_id))

    def match_order(incoming_side, incoming_price, incoming_qty, incoming_id, is_ioc_or_market):
        nonlocal trades
        remaining = incoming_qty

        if incoming_side == 'buy':
            # Match against sell_book (lowest price first, earliest arrival first)
            while remaining > 0 and sell_book:
                price, arrival_index, resting_id = heapq.heappop(sell_book)

                if resting_id not in resting:
                    continue

                resting_side, resting_price, resting_qty, _ = resting[resting_id]

                if resting_price > incoming_price:
                    # No more matches possible
                    heapq.heappush(sell_book, (price, arrival_index, resting_id))
                    break

                trade_qty = min(remaining, resting_qty)
                trades.append([incoming_id, resting_id, resting_price, trade_qty])
                remaining -= trade_qty

                if resting_qty > trade_qty:
                    # Resting order partially filled, keep it in the book
                    resting[resting_id] = (resting_side, resting_price, resting_qty - trade_qty, arrival_index)
                    heapq.heappush(sell_book, (price, arrival_index, resting_id))
                else:
                    # Resting order fully filled
                    del resting[resting_id]
        else:
            # Match against buy_book (highest price first, earliest arrival first)
            while remaining > 0 and buy_book:
                neg_price, arrival_index, resting_id = heapq.heappop(buy_book)
                resting_price = -neg_price

                if resting_id not in resting:
                    continue

                resting_side, _, resting_qty, _ = resting[resting_id]

                if resting_price < incoming_price:
                    # No more matches possible
                    heapq.heappush(buy_book, (neg_price, arrival_index, resting_id))
                    break

                trade_qty = min(remaining, resting_qty)
                trades.append([resting_id, incoming_id, resting_price, trade_qty])
                remaining -= trade_qty

                if resting_qty > trade_qty:
                    # Resting order partially filled, keep it in the book
                    resting[resting_id] = (resting_side, resting_price, resting_qty - trade_qty, arrival_index)
                    heapq.heappush(buy_book, (neg_price, arrival_index, resting_id))
                else:
                    # Resting order fully filled
                    del resting[resting_id]

        # If limit order, add remaining quantity to the book
        if not is_ioc_or_market and remaining > 0:
            add_limit_order(incoming_id, incoming_side, incoming_price, remaining, next_arrival[0])

        next_arrival[0] += 1

    for order in orders:
        if order[0] == 'limit':
            _, order_id, side, price, qty = order
            match_order(side, price, qty, order_id, False)
            # If no match, add to book
            if order_id not in resting:
                add_limit_order(order_id, side, price, qty, next_arrival[0])
                next_arrival[0] += 1

        elif order[0] == 'ioc':
            _, order_id, side, price, qty = order
            match_order(side, price, qty, order_id, True)

        elif order[0] == 'market':
            _, order_id, side, qty = order
            # Market order matches at any price
            if side == 'buy':
                match_order(side, float('inf'), qty, order_id, True)
            else:
                match_order(side, 0, qty, order_id, True)

        elif order[0] == 'cancel':
            _, order_id = order
            if order_id in resting:
                side, price, _, _ = resting[order_id]
                del resting[order_id]
                # Remove from book (lazy deletion - will skip if not in resting)

    return trades

